  expired_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  admin shopping_mall_admins @relation(fields: [shopping_mall_admin_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([shopping_mall_admin_id, created_at], map: "shopping_mall_admin_sessions_shopping_mall_admin_id_cr_39834090")
  @@index([expired_at])
}

/// Password reset tokens issued to administrators for account recovery. Each
/// token is one-time use, has a fixed expiration, and tracks the IP and user
/// agent of the reset request. Immutable audit trail that ensures security
/// and compliance.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_admin_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Admin who requested the password reset. {@link shopping_mall_admins.id}.
  admin_id String @db.Uuid

  /// Unique cryptographic token generated for password reset. Must be stored
