  /// shopping_mall_customers.id}.
  shopping_mall_customer_id String @db.Uuid

  /// Client's IP address at login time.
  ip String

  /// URL of the page where login occurred.
  href String

  /// Referrer header from the client's browser.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires. Always set to 30 minutes after
  /// created_at for access token, 30 days after for refresh token. Never null
