  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belongs to customer account. {@link shopping_mall_customers.id}.
  shopping_mall_customer_id String @db.Uuid

  /// Unique verification token. Generated as cryptographically random string.
  token String

  /// When this token expires. Must be enforced by the application to
