    Date.now() - 7 * 24 * 60 * 60 * 1000,
  ).toISOString();
  // Call the endpoint to fetch order item snapshots filtered by product_id and date range
  const snapshotRequest: IShoppingMallOrderItemSnapshot.IRequest = {
    product_id,
    created_at_from: oneWeekAgo,
