}): Promise<IPageIShoppingMallOrder.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;
  const where: Prisma.shopping_mall_ordersWhereInput = {
    ...(props.body.order_number && { id: props.body.order_number }),
    ...(props.body.customer_id && { customer_id: props.body.customer_id }),
    ...(props.body.seller_id && { seller_id: props.body.seller_id }),
    ...(props.body.status && { status: props.body.status }),
    created_at: {
      ...(props.body.created_at_start && { gte: props.body.created_at_start }),
      ...(props.body.created_at_end && { lte: props.body.created_at_end }),
    },
  };
  // Customer email substring match via join
  if (props.body.customer_email) {
    where.customer = {
      email: { contains: props.body.customer_email, mode: "insensitive" },
    };
  }
  // Seller shop name substring match via join through order_items
  if (props.body.seller_shop_name) {
    const sellerIds = (
      await MyGlobal.prisma.shopping_mall_customers.findMany({
        where: {
          display_name: {
            contains: props.body.seller_shop_name,
            mode: "insensitive",
          },
        },
        select: { id: true },
      })
    ).map((c) => c.id);
    where.orderItems = {
      some: {
        seller: {
          id: { in: sellerIds },
        },
      },
    };
  }
  // Fetch paginated data
  const orders = await MyGlobal.prisma.shopping_mall_orders.findMany({
    where,
    skip,
    take: limit,
    orderBy: { created_at: "desc" },
    ...ShoppingMallOrderAtSummaryTransformer.select(),
  });
  // Count total records
  const total = await MyGlobal.prisma.shopping_mall_orders.count({ where });
  return {
    data: await ArrayUtil.asyncMap(
      orders,
      ShoppingMallOrderAtSummaryTransformer.transform,
    ),
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
  };
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAuthSellerRefresh(props: {
  body: IShoppingMallSeller.IRefresh;
}): Promise<IShoppingMallSeller.IAuthorized> {
  // 1. Verify refresh token
  let decoded: {
    id: string;
    session_id: string;
    type: "seller";
  };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as typeof decoded;
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  // 2. Validate type
  if (decoded.type !== "seller") {
    throw new HttpException("Invalid token type", 403);
  }
  // 3. Validate session
  const session = await MyGlobal.prisma.shopping_mall_seller_sessions.findFirst(
    {
      where: {
        id: decoded.session_id,
        shopping_mall_seller_id: decoded.id,
      },
    },
  );
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  // 4. Validate seller account
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUniqueOrThrow({
    where: { id: decoded.id },
  });
  if (seller.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }
  // 5. Generate new tokens (SAME session_id)
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 30 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
  const token = {
    access: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        created_at: now.toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "30m", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        tokenType: "refresh",
        created_at: now.toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "30d", issuer: "autobe" },
    ),
  };
  // 6. Update session expiration
  await MyGlobal.prisma.shopping_mall_seller_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshExpires },
  });
  return {
    id: decoded.id,
    expired_at: accessExpires.toISOString() as string &
      tags.Format<"date-time">,
    token: {
      access: token.access,
      refresh: token.refresh,
      refreshable_until: refreshExpires.toISOString() as string &
        tags.Format<"date-time">,
      expired_at: accessExpires.toISOString() as string &
        tags.Format<"date-time">,
    },
  };
}

