export async function postShoppingMallAdminInventoryVariantIdAdjust(props: {
  admin: AdminPayload;
  variantId: string;
  body: IShoppingMallInventoryLog.IAdjust;
}): Promise<void> {
  const variant =
    await MyGlobal.prisma.shopping_mall_product_variants.findUniqueOrThrow({
      where: { id: props.variantId },
    });
  if (props.body.reason !== "adjustment" && props.body.reason !== "loss") {
    throw new HttpException(
      'Reason must be either "adjustment" or "loss"',
      400,
    );
  }
  await MyGlobal.prisma.$transaction(async (prisma) => {
    const createdAt = toISOStringSafe(new Date());
    const updatedAt = toISOStringSafe(new Date());
    await prisma.shopping_mall_inventory_logs.create({
      data: {
        id: v4(),
        variant_id: props.variantId,
        change_quantity: props.body.quantity satisfies number as number,
        reason: props.body.reason satisfies "adjustment" | "loss" as
          | "adjustment"
          | "loss",
        created_at: createdAt,
        updated_at: updatedAt,
      },
    });
    await prisma.shopping_mall_product_variants.update({
      where: { id: props.variantId },
      data: {
        stock_quantity: {
          increment: props.body.quantity satisfies number as number,
        },
      },
    });
  });
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAdminRefundRequestsRequestIdRespond(props: {
  admin: AdminPayload;
  requestId: string & tags.Format<"uuid">;
  body: IShoppingMallRefundRequest.IRespond;
}): Promise<void> {
  const request =
    await MyGlobal.prisma.shopping_mall_refund_requests.findUniqueOrThrow({
      where: { id: props.requestId },
      select: {
        id: true,
        status: true,
        order_item_id: true,
        customer_id: true,
        reason: true,
        responded_at: true,
      },
    });
  if (request.status !== "pending") {
    throw new HttpException("Refund request is no longer pending", 400);
  }
  const now = toISOStringSafe(new Date()) as string & tags.Format<"date-time">;
  // Validate reason length for 'reject'
  if (props.body.action === "reject") {
    if (props.body.reason.length < 10 || props.body.reason.length > 500) {
      throw new HttpException(
        "Reason must be between 10 and 500 characters",
        400,
      );
    }
  }
  await MyGlobal.prisma.$transaction(async (prisma) => {
    // Update refund request
    await prisma.shopping_mall_refund_requests.update({
      where: { id: props.requestId },
      data: {
        status: props.body.action,
        responded_at: now,
        responder_id: props.admin.id,
        updated_at: now,
      },
    });
    // Get existing snapshot count for versioning
    const snapshotCount =
      await prisma.shopping_mall_refund_request_snapshots.count({
        where: { refund_request_id: props.requestId },
      });
    // Create snapshot
    await prisma.shopping_mall_refund_request_snapshots.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        refund_request_id: props.requestId,
        version: snapshotCount + 1,
        reason: request.reason,
        status: props.body.action,
        responder_id: props.admin.id,
        response_reason:
          props.body.action === "approve" ? null : props.body.reason,
        changed_at: now,
        changed_by: "admin",
      },
    });
    // If approve: restore inventory
    if (props.body.action === "approve") {
      const orderItem =
        await prisma.shopping_mall_order_items.findUniqueOrThrow({
          where: { id: request.order_item_id },
          select: { shopping_mall_product_variant_id: true, quantity: true },
        });
      await prisma.shopping_mall_inventory_logs.create({
        data: {
          id: v4() as string & tags.Format<"uuid">,
          variant_id: orderItem.shopping_mall_product_variant_id,
          change_quantity: orderItem.quantity,
          reason: "refund",
          reference_id: props.requestId,
          created_at: now,
          updated_at: now,
        },
      });
    }
  });
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAuthAdminJoin(props: {
  ip: string;
  body: IShoppingMallAdmin.IJoin;
}): Promise<IShoppingMallAdmin.IAuthorized> {
  // 1. Check duplicate admin email
  const existing = await MyGlobal.prisma.shopping_mall_admins.findFirst({
    where: { email: props.body.email },
  });
  if (existing) throw new HttpException("Email already registered", 409);
  // 2. Create admin record
  const admin = await MyGlobal.prisma.shopping_mall_admins.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      email: props.body.email,
      password_hash: await PasswordUtil.hash(props.body.password),
      is_active: true,
      status: "active",
      created_at: toISOStringSafe(new Date()) as string &
        tags.Format<"date-time">,
      updated_at: toISOStringSafe(new Date()) as string &
        tags.Format<"date-time">,
      deleted_at: null,
      suspended_at: null,
    },
  });
  // 3. Create admin session
  const accessExpires = new Date(Date.now() + 30 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.shopping_mall_admin_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_admin_id: admin.id,
      ip: props.ip ?? "",
      href: "",
      referrer: null,
      created_at: toISOStringSafe(new Date()) as string &
        tags.Format<"date-time">,
      expired_at: toISOStringSafe(accessExpires) as string &
        tags.Format<"date-time">,
    },
  });
  // 4. Generate JWT tokens
  const access: string = jwt.sign(
    {
      type: "admin",
      id: admin.id,
      session_id: session.id,
      created_at: toISOStringSafe(new Date()) as string &
        tags.Format<"date-time">,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "30m", issuer: "autobe" },
  );
  const refresh: string = jwt.sign(
    {
      type: "admin",
      id: admin.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()) as string &
        tags.Format<"date-time">,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "30d", issuer: "autobe" },
  );
  const token: IAuthorizationToken = {
    access,
    refresh,
    expired_at: toISOStringSafe(accessExpires) as string &
      tags.Format<"date-time">,
    refreshable_until: toISOStringSafe(refreshExpires) as string &
      tags.Format<"date-time">,
  };
  // 5. Return IAuthorized structure
  return {
    access_token: access,
    refresh_token: refresh,
    admin_id: admin.id,
    token,
  } satisfies IShoppingMallAdmin.IAuthorized;
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAuthAdminLogin(props: {
  ip: string;
  body: IShoppingMallAdmin.ILogin;
}): Promise<IShoppingMallAdmin.IAuthorized> {
  // 1. Find admin by email with password_hash
  const admin = await MyGlobal.prisma.shopping_mall_admins.findFirst({
    where: { email: props.body.email },
    select: {
      id: true,
      password_hash: true,
      status: true,
      suspended_at: true,
    },
  });
  // 2. Validate admin exists and is not suspended
  if (!admin) throw new HttpException("Invalid credentials", 401);
  if (admin.suspended_at !== null) throw new HttpException("Forbidden", 403);
  // 3. Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    admin.password_hash,
  );
  if (!isValid) throw new HttpException("Invalid credentials", 401);
  // 4. Create new session
  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 30 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
  );
  const session = await MyGlobal.prisma.shopping_mall_admin_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_admin_id: admin.id,
      ip: props.ip ?? "",
      href: "",
      referrer: "",
      created_at: now,
      expired_at: accessExpires,
    },
  });
  // 5. Generate JWT tokens
  const token = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "30m", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "30d", issuer: "autobe" },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };
  // 6. Return IAuthorized
  return {
    access_token: token.access,
    refresh_token: token.refresh,
    admin_id: admin.id as string & tags.Format<"uuid">,
    token: {
      access: token.access,
      refresh: token.refresh,
      expired_at: token.expired_at,
      refreshable_until: token.refreshable_until,
    },
  } satisfies IShoppingMallAdmin.IAuthorized;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
