export async function postShoppingMallSellerProductsProductIdImages(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IShoppingMallProductImage.IUpload;
}): Promise<IShoppingMallProductImage> {
  // Validate product exists and belongs to seller
  const product =
    await MyGlobal.prisma.shopping_mall_products.findUniqueOrThrow({
      where: {
        id: props.productId,
        seller_id: props.seller.id,
        deleted_at: null,
      },
    });
  // Count existing images to enforce limit
  const existingCount =
    await MyGlobal.prisma.shopping_mall_product_images.count({
      where: { product_id: props.productId, deleted_at: null },
    });
  if (existingCount >= 10) {
    throw new HttpException("Maximum 10 images per product", 400);
  }
  // Calculate next position
  const maxPosition =
    await MyGlobal.prisma.shopping_mall_product_images.aggregate({
      _max: { position: true },
      where: { product_id: props.productId, deleted_at: null },
    });
  const position =
    maxPosition._max.position !== null ? maxPosition._max.position + 1 : 0;
  // Validate image_url is valid URI using typia
  const validatedImageUrl = typia.assert<string & tags.Format<"uri">>(
    props.body.image_url,
  );
  // Create image record
  const created = await MyGlobal.prisma.shopping_mall_product_images.create({
    data: {
      id: v4(),
      product_id: props.productId,
      image_url: validatedImageUrl,
      position,
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
      deleted_at: null,
    },
    ...ShoppingMallProductImageTransformer.select(),
  });
  return await ShoppingMallProductImageTransformer.transform(created);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putShoppingMallSellerProductsProductIdImagesReorder(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IShoppingMallProductImage.IReorderRequest;
}): Promise<IShoppingMallProductImage.IReorderResponse> {
  // Ensure seller owns the product
  const product = await MyGlobal.prisma.shopping_mall_products.findFirst({
    where: {
      id: props.productId,
      seller_id: props.seller.id,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!product) {
    throw new HttpException("Product not found or access denied", 404);
  }
  // Validate image IDs belong to product and positions are unique/valid
  const imagesInDb =
    await MyGlobal.prisma.shopping_mall_product_images.findMany({
      where: {
        product_id: props.productId,
        deleted_at: null,
      },
      select: { id: true },
    });
  const imageIds = new Set(imagesInDb.map((img) => img.id));
  const positions = new Set<number>();
  for (const item of props.body.images) {
    if (!imageIds.has(item.id)) {
      throw new HttpException("Image does not belong to this product", 400);
    }
    if (item.position < 0 || item.position > 9) {
      throw new HttpException("Position must be between 0 and 9", 400);
    }
    if (positions.has(item.position)) {
      throw new HttpException("Duplicate position values not allowed", 400);
    }
    positions.add(item.position);
  }
  // Atomically update all image positions within transaction
  await MyGlobal.prisma.$transaction(
    props.body.images.map((item) =>
      MyGlobal.prisma.shopping_mall_product_images.update({
        where: { id: item.id },
        data: { position: item.position },
      }),
    ),
  );
  // Snapshot is automatically created by the system via Prisma triggers
  // as defined in 12-snapshot-principle.md: every product edit triggers snapshot
  return { success: true };
}

